#include<limits.h>
/*@
	assigns \nothing;
	ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();
#define N 10000
#define fun bor
#include <assert.h>
int bor (int x[N])
{
  int i;
  long long res;
  res = x[0];
  for (i = 1; i < N; i++) {
    res = res | x[i];
  }
  @ assert INT_MIN <= res <= INT_MAX;
  @ assert (int)res == res;
  return res;
}
/* Logic function definition: OR over range */
/*@
	@ logic integer bor_range(int *a, integer lo, integer hi) = lo >= hi ? 0 : (a[lo] | bor_range(a, lo+1, hi));
*/
/*@
	requires \valid_read(x+(0..N-1));
	assigns \nothing;
	ensures \result == (int)bor_range(x, 0, N);
*/
int main ()
{
  int x[N];
  int temp;
  int ret;
  int ret2;
  int ret5;

  /* First loop: fill array */
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  @ loop invariant 0 <= i <= N;
  @ loop invariant \forall integer j; 0 <= j < i ==> x[j] is assigned;
  @ loop invariant (unknown (\valid(x)));
  @ loop assigns i, x[0..N-1];
  @ loop variant N - i;

  ret = bor(x);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  ret2 = bor(x);
  @ assert x[0] == \old(x[1]) && x[1] == \old(x[0]);
  @ assert \old(bor_range(x, 0, N)) == bor_range(x, 0, N);
  @ assert ret == ret2;

  /* Rotation loop */
  temp=x[0];
  for(int i =0 ; i<N-1; i++){
     x[i] = x[i+1];
  }
  x[N-1] = temp;
  @ loop invariant 0 <= i <= N-1;
  @ loop invariant \forall integer k; 0 <= k < i ==> x[k] == \old(x[k+1]);
  @ loop invariant \forall integer k; i <= k < N ==> x[k] == \old(x[k - i]);
  @ loop invariant bor_range(x, 0, N) == \old(bor_range(x, 0, N));
  @ loop assigns i, x[0..N-1];
  @ loop variant N - i;

  ret5 = bor(x);
  @ assert ret == ret5;

  @ assert !(ret != ret2 || ret !=ret5);
  return 1;
}
